  it.each([
    ['Enter', 'beta'],
    [' ', 'beta'],
    ['ArrowDown', 'beta'],
    ['ArrowUp', 'beta'],
  ])('opens from Trigger %j and focuses selected option %s once', async (key, expectedValue) => {
    // T-BASE-SELECT-TRIGGER-0001-CASE-KEYBOARD
